#!/data/data/com.termux/files/usr/bin/bash
set -euo pipefail
CAMPAIGN=OBSIDIANTI_MWNI_HEAVY1_SIDE_GIF_v1.4.9
AUTHORITY=TERMUX_GIT_ONLY
SELF="$(realpath "$0")"
LAUNCHER_SHA256="$(sha256sum "$SELF" | cut -d' ' -f1)"
PAYLOAD_SHA256=9a77572d26c1a1c091749183c89888ae5de5eff92aac24edbda48adaa601c9ae
echo "CAMPAIGN=$CAMPAIGN"
echo "AUTHORITY=$AUTHORITY"
echo "LAUNCHER_SHA256=$LAUNCHER_SHA256"
echo "PAYLOAD_SHA256=$PAYLOAD_SHA256"
WORKDIR="$(mktemp -d "${TMPDIR:-${PREFIX:-/data/data/com.termux/files/usr}/tmp}/obs-heavy1-sidegif-v149.XXXXXXXX")"
trap 'rm -rf "$WORKDIR"' EXIT
base64 -d > "$WORKDIR/payload.tar.gz" <<'PAYLOAD_BASE64_END'

PAYLOAD_BASE64_END
printf '%s  %s\n' "$PAYLOAD_SHA256" "$WORKDIR/payload.tar.gz" | sha256sum -c -
mkdir -p "$WORKDIR/packet"
tar -xzf "$WORKDIR/payload.tar.gz" -C "$WORKDIR/packet" --no-same-owner
if [ "${1:-}" = '--verify-packet' ]; then
  python3 "$WORKDIR/packet/test_gif.py"
  echo 'HEAVY1_SIDE_GIF_PACKET_TESTS=PASS'
  exit 0
fi
exec python3 "$WORKDIR/packet/driver.py" "$WORKDIR/packet" "$SELF" "$LAUNCHER_SHA256"
